<https://example.org/openevidence/questions/q_pulmonary_embolism_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is apixaban compared with other agents for Pulmonary Embolism?"^^xsd:string ;
    oe:answerText "Pulmonary embolism (PE) is the leading cause of in-hospital death and the third most frequent cause of cardiovascular death. The clinical presentation of PE is variable, and choosing the appropriate treatment for individual patients can be challenging."^^xsd:string ;
    oe:belongsToSpecialty "Pulmonology" ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_pulmonary_embolism_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_pulmonary_embolism_efficacy-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_pulmonary_embolism_efficacy-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_pulmonary_embolism_efficacy-con> ;
    holon:evidenceQualityThreshold "0.25"^^xsd:decimal .

<https://example.org/openevidence/drugs/apixaban> oe:treats <https://example.org/openevidence/diseases/pulmonary_embolism> .
